update HIT_LOAD_LOG 
  set MIN_UTII_RETRIEVED = #{minUtiiRetrieved, jdbcType=INTEGER},
  MAX_UTII_RETRIEVED = #{maxUtiiRetrieved, jdbcType=INTEGER},
  MAX_UTII_CHECKED = #{maxUtiiChecked, jdbcType=INTEGER},
  NO_OF_RETRIEVED_DOCS = #{noOfRetrievedDocs, jdbcType=INTEGER}
where log_id = #{logID, jdbcType=INTEGER}


update HIT_LOAD_LOG 
  set NO_OF_FAILED_DOCS = #{noOfFailedDocs, jdbcType=INTEGER},
  NO_OF_RETRIEVED_DOCS = #{noOfRetrievedDocs, jdbcType=INTEGER},
  NO_OF_SUCCESSFUL_DOCS = #{noOfSuccessfulDocs, jdbcType=INTEGER}
where log_id = #{logID, jdbcType=INTEGER}

update
CODED_HIT_RACE_DESC set RACE = #{parameterValue1} , ETHNICITY =
#{parameterValue2},UPDATED_DATE = TRUNC(SYSDATE), UPDATED_BY = #{userId}  WHERE RACE_VALUE = #{parameterName}
